	public void assignVariant( AssignVariantToMediaAssetCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignVariant(command.getMediaAssetId(), command.getAssignment());

	}

	/**
	 * unAssign Variant on MediaAsset
	 * @param		command UnAssignVariantFromMediaAssetCommand
	 */
	public void unAssignVariant( UnAssignVariantFromMediaAssetCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignVariant(command.getMediaAssetId());
	}
	




